// beacon-chain/core/peerdas/p2p_interface.go
func VerifyDataColumnSidecarInclusionProof(sidecar blocks.RODataColumn) error {
    if sidecar.SignedBlockHeader == nil || sidecar.SignedBlockHeader.Header == nil {
        return ErrNilBlockHeader
    }
    root := sidecar.SignedBlockHeader.Header.BodyRoot
    if len(root) != fieldparams.RootLength {
        return ErrBadRootLength
    }
    leaves := blocks.LeavesFromCommitments(sidecar.KzgCommitments)
    sparse, err := trie.GenerateTrieFromItems(leaves, fieldparams.LogMaxBlobCommitments)
    if err != nil { return errors.Wrap(err, "generate trie from items") }
    hashTreeRoot, err := sparse.HashTreeRoot()
    if err != nil { return errors.Wrap(err, "hash tree root") }
    verified := trie.VerifyMerkleProof(root, hashTreeRoot[:], kzgPosition, sidecar.KzgCommitmentsInclusionProof)
    if !verified {
        return ErrInvalidInclusionProof
    }
    return nil
}

// beacon-chain/verification/data_column.go
func (dv *RODataColumnsVerifier) SidecarInclusionProven() (err error) {
    if ok, err := dv.results.cached(RequireSidecarInclusionProven); ok {
        return err
    }
    defer dv.recordResult(RequireSidecarInclusionProven, &err)
    startTime := time.Now()
    for _, dataColumn := range dv.dataColumns {
        k, keyErr := inclusionProofKey(dataColumn)
        if keyErr == nil {
            if _, ok := dv.ic.Get(k); ok {
                continue  // CACHED - skip verification!
            }
        } else {
            log.WithError(keyErr).Error("Failed to get inclusion proof key")
        }
        if err = peerdas.VerifyDataColumnSidecarInclusionProof(dataColumn); err != nil {
            return columnErrBuilder(ErrSidecarInclusionProofInvalid)
        }
        if keyErr == nil {
            dv.ic.Add(k, struct{}{})
        }
    }
    return nil
}
```

**Gossip validation pipeline (validate_data_column.go):**
```go
func (s *Service) validateDataColumn(ctx context.Context, pid peer.ID, msg *pubsub.Message) (pubsub.ValidationResult, error) {
    // ... decode, convert ...
    verifier := s.newColumnsVerifier(roDataColumns, verification.GossipDataColumnSidecarRequirements)

    if err := verifier.ValidFields(); err != nil { return pubsub.ValidationReject, err }
    if err := verifier.CorrectSubnet(...); err != nil { return pubsub.ValidationReject, err }
    if err := verifier.NotFromFutureSlot(); err != nil { return pubsub.ValidationIgnore, err }
    if err := verifier.SlotAboveFinalized(); err != nil { return pubsub.ValidationIgnore, err }
    if err := verifier.SidecarParentSeen(...); err != nil {
        // Goes async to fetch parent, returns IGNORE
        return pubsub.ValidationIgnore, err
    }
    if err := verifier.SidecarParentValid(...); err != nil { return pubsub.ValidationReject, err }
    if err := verifier.ValidProposerSignature(ctx); err != nil { return pubsub.ValidationReject, err }
    if err := verifier.SidecarParentSlotLower(); err != nil { return pubsub.ValidationReject, err }
    if err := verifier.SidecarDescendsFromFinalized(); err != nil { return pubsub.ValidationReject, err }

    // [REJECT] inclusion proof check
    if err := verifier.SidecarInclusionProven(); err != nil {
        return pubsub.ValidationReject, err
    }

    // [REJECT] KZG proof check via batch verifier
    validationResult, err := s.validateWithKzgBatchVerifier(ctx, roDataColumns)
    if validationResult != pubsub.ValidationAccept {
        return validationResult, err
    }
    verifier.SatisfyRequirement(verification.RequireSidecarKzgProofVerified)

    // ... rest of validation ...
}
```

